const { width: FIELD_WIDTH, height: FIELD_HEIGHT, rowsHex: FIELD_ROWS } = WORLD_REFERENCE_BIOME_FIELD;

/** Unpacked once on first use — two Float32Arrays in 0..1. */
const UNPACKED = (() => {
	const forest = new Float32Array(FIELD_WIDTH * FIELD_HEIGHT);
	const arid = new Float32Array(FIELD_WIDTH * FIELD_HEIGHT);
	for (let y = 0; y < FIELD_HEIGHT; y += 1) {
		const row = FIELD_ROWS[y];
		for (let x = 0; x < FIELD_WIDTH; x += 1) {
			const index = y * FIELD_WIDTH + x;
			forest[index] = parseInt(row[x * 2], 16) / 15;
			arid[index] = parseInt(row[x * 2 + 1], 16) / 15;
		}
	}
	return { forest, arid };
})();

function bilinear(field, normalizedX, normalizedY) {
	const fx = normalizedX * FIELD_WIDTH - 0.5;
	const fy = normalizedY * FIELD_HEIGHT - 0.5;
	const x0 = Math.floor(fx);
	const y0 = Math.floor(fy);
	const tx = fx - x0;
	const ty = fy - y0;
	const at = (x, y) => {
		const cx = x < 0 ? 0 : x >= FIELD_WIDTH ? FIELD_WIDTH - 1 : x;
		const cy = y < 0 ? 0 : y >= FIELD_HEIGHT ? FIELD_HEIGHT - 1 : y;
		return field[cy * FIELD_WIDTH + cx];
	};
	const top = at(x0, y0) * (1 - tx) + at(x0 + 1, y0) * tx;
	const bottom = at(x0, y0 + 1) * (1 - tx) + at(x0 + 1, y0 + 1) * tx;
	return top * (1 - ty) + bottom * ty;
}

/**
 * How wooded the owner map draws this spot, in [0, 1].
 * @param {number} normalizedX
 * @param {number} normalizedY
 */
export function sampleMapForest01(normalizedX, normalizedY) {
	return bilinear(UNPACKED.forest, normalizedX, normalizedY);
}

/**
 * How arid the owner map draws this spot, in [0, 1]. Dorne and the Red Waste are the two places this
 * goes high; everywhere green reads zero.
 * @param {number} normalizedX
 * @param {number} normalizedY
 */
export function sampleMapAridity01(normalizedX, normalizedY) {
	return bilinear(UNPACKED.arid, normalizedX, normalizedY);
}
